//! Dense-peak verification (M7 step 4) on real artifacts
//! (`tests/fixtures/aipeak/`, regenerated by the ignored `aipeak_fixtures.rs`).
//!
//! * Mainnet's rules: upstream's consensus verifier (the `%ai-pow-verify-v2`
//!   jet's jam entry) accepts the fixture wins under `ConsensusBatch` with the
//!   context and digest this registry derives, and refuses a Legacy-rules
//!   certificate; the registry agrees on both.
//! * Every rejection the registry adds fires on a real artifact, each with its
//!   own reason, so disabling any one check changes the outcome of its test.

use std::sync::OnceLock;

use ai_pow_miner::certificate_noun::{
    verify_ai_pow_block_artifact_jam_with_verification_rules, AiPowBlockVerifyOutcome,
    CertificateNounLimits,
};
use ai_pow_zk::proof_rules::VerificationRules;
use nockmark_registry::aipow::challenge32;
use nockmark_registry::aipow_peak::{verify_peak_submission, AiPeakVerifier};
use tock::aipow_peak::{
    peak_target_for_attempts, AI_PEAK_MAX_PATTERN_LEN, AI_PEAK_SUBMISSION_BLOB_MAX,
    PEAK_TICKETS_PER_EXTRANONCE,
};

fn dir() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/aipeak")
}

fn fx(name: &str) -> Vec<u8> {
    std::fs::read(dir().join(name)).unwrap_or_else(|e| panic!("fixture {name}: {e}"))
}

struct Manifest {
    nonce: u64,
    target: [u8; 32],
    indices: Vec<u64>,
}

fn manifest() -> Manifest {
    let v: serde_json::Value =
        serde_json::from_slice(&fx("manifest.json")).expect("manifest.json");
    Manifest {
        nonce: v["nonce"].as_u64().unwrap(),
        target: tock::aipow::parse_hex32(v["target"].as_str().unwrap()).unwrap(),
        indices: v["indices"]
            .as_array()
            .unwrap()
            .iter()
            .map(|x| x.as_u64().unwrap())
            .collect(),
    }
}

fn verifier() -> &'static AiPeakVerifier {
    static V: OnceLock<AiPeakVerifier> = OnceLock::new();
    V.get_or_init(|| {
        let t = std::time::Instant::now();
        let v = AiPeakVerifier::build().expect("derive the dense-peak verifier context");
        eprintln!("dense-peak context derived in {:.2}s", t.elapsed().as_secs_f64());
        v
    })
}

fn verify(challenge: &[u8; 32], target: &[u8; 32], index: u64, jam: &[u8]) -> Result<(), String> {
    verifier().verify(challenge, target, index, jam)
}

#[test]
fn fixtures_are_for_the_fixture_tier() {
    let m = manifest();
    assert_eq!(Some(m.target), peak_target_for_attempts(1 << 12));
    assert_eq!(m.indices.len(), 3);
    assert!(m.indices.windows(2).all(|w| w[0] < w[1]));
}

/// The registry's derived context is the one the certificates were proved
/// for, and upstream's own consensus verifier agrees with the registry: it
/// accepts the Hardened wins under ConsensusBatch and refuses the Legacy one.
#[test]
fn upstream_consensus_and_the_registry_agree_on_mainnet_rules() {
    let m = manifest();
    let challenge = challenge32(m.nonce);
    let v = verifier();
    for (i, &index) in m.indices.iter().enumerate() {
        let jam = fx(&format!("win-{i}.jam"));
        let out = verify_ai_pow_block_artifact_jam_with_verification_rules(
            &jam,
            CertificateNounLimits::default(),
            &challenge,
            &m.target,
            AI_PEAK_MAX_PATTERN_LEN,
            v.context(),
            v.pinned_digest(),
            VerificationRules::ConsensusBatch,
        )
        .unwrap_or_else(|e| panic!("win {i}: upstream consensus verify: {e:?}"));
        assert!(matches!(out, AiPowBlockVerifyOutcome::Dense(_)), "win {i}");
        verify(&challenge, &m.target, index, &jam).unwrap_or_else(|e| panic!("win {i}: {e}"));
    }

    let legacy = fx("legacy-win-0.jam");
    let upstream = verify_ai_pow_block_artifact_jam_with_verification_rules(
        &legacy,
        CertificateNounLimits::default(),
        &challenge,
        &m.target,
        AI_PEAK_MAX_PATTERN_LEN,
        v.context(),
        v.pinned_digest(),
        VerificationRules::ConsensusBatch,
    );
    assert!(upstream.is_err(), "upstream must refuse a Legacy certificate");
    let err = verify(&challenge, &m.target, m.indices[0], &legacy).unwrap_err();
    assert!(err.contains("DigestMismatch"), "{err}");
}

#[test]
fn rejects_an_oversized_blob() {
    let m = manifest();
    let mut jam = fx("win-0.jam");
    jam.resize(AI_PEAK_SUBMISSION_BLOB_MAX + 1, 0);
    let err = verify(&challenge32(m.nonce), &m.target, m.indices[0], &jam).unwrap_err();
    assert!(err.contains("exceeds"), "{err}");
}

#[test]
fn rejects_an_index_whose_extranonce_is_not_u32() {
    let m = manifest();
    let index = (u64::from(u32::MAX) + 1) * PEAK_TICKETS_PER_EXTRANONCE;
    let err = verify(&challenge32(m.nonce), &m.target, index, &fx("win-0.jam")).unwrap_err();
    assert!(err.contains("extranonce does not fit"), "{err}");
}

#[test]
fn rejects_bytes_that_are_not_an_artifact() {
    let m = manifest();
    let err = verify(&challenge32(m.nonce), &m.target, 0, b"not an ai-pow artifact").unwrap_err();
    assert!(err.contains("artifact decode"), "{err}");
}

/// Valid mainnet work of another statement (canonical MoE) for this very
/// challenge.
#[test]
fn rejects_a_moe_artifact() {
    let m = manifest();
    let err = verify(&challenge32(m.nonce), &m.target, 0, &fx("moe.jam")).unwrap_err();
    assert!(err.contains("MoE tail"), "{err}");
}

/// Win 0 claimed one extranonce later (same tile): the stored attempt index
/// must name the ticket that was proved.
#[test]
fn rejects_a_win_claimed_at_another_extranonce() {
    let m = manifest();
    let index = m.indices[0] + PEAK_TICKETS_PER_EXTRANONCE;
    let err = verify(&challenge32(m.nonce), &m.target, index, &fx("win-0.jam")).unwrap_err();
    assert!(err.contains("Pearl header"), "{err}");
}

/// Win 0 claimed at the next tile of the same extranonce.
#[test]
fn rejects_a_win_claimed_at_another_tile() {
    let m = manifest();
    let index = m.indices[0] + 1;
    assert_eq!(
        index / PEAK_TICKETS_PER_EXTRANONCE,
        m.indices[0] / PEAK_TICKETS_PER_EXTRANONCE
    );
    let err = verify(&challenge32(m.nonce), &m.target, index, &fx("win-0.jam")).unwrap_err();
    assert!(err.contains("opened tile"), "{err}");
}

/// Work for one challenge replayed onto another.
#[test]
fn rejects_a_win_of_another_challenge() {
    let m = manifest();
    let err =
        verify(&challenge32(m.nonce + 1), &m.target, m.indices[0], &fx("win-0.jam")).unwrap_err();
    assert!(err.contains("Pearl header"), "{err}");
}

/// A real proof whose jackpot does not clear a harder tier: consensus's own
/// `jackpot ≤ T·F` gate, at the target the registry issued.
#[test]
fn rejects_a_win_above_the_target() {
    let m = manifest();
    let hard = peak_target_for_attempts(1 << 36).unwrap();
    let err = verify(&challenge32(m.nonce), &hard, m.indices[0], &fx("win-0.jam")).unwrap_err();
    assert!(err.starts_with("consensus verify"), "{err}");
}

/// One byte flipped in the middle of the artifact, inside the certificate.
#[test]
fn rejects_a_tampered_certificate() {
    let m = manifest();
    let mut jam = fx("win-1.jam");
    let mid = jam.len() / 2;
    jam[mid] ^= 0x01;
    let err = verify(&challenge32(m.nonce), &m.target, m.indices[1], &jam).unwrap_err();
    assert!(
        err.starts_with("consensus verify") || err.starts_with("artifact decode"),
        "{err}"
    );
}

/// The context must be the one whose digest the server pins.
#[test]
fn rejects_a_context_that_is_not_the_pinned_one() {
    let m = manifest();
    let v = verifier();
    let mut other = *v.pinned_digest();
    other[0] ^= 1;
    let err = verify_peak_submission(
        &challenge32(m.nonce),
        &m.target,
        v.context(),
        &other,
        m.indices[0],
        &fx("win-0.jam"),
    )
    .unwrap_err();
    assert!(err.contains("context digest does not match"), "{err}");
}
